test('REQ-2-3#2: REQ-2-3: Grant Repository Access to People and Teams - Scenario 2', async ({ page }) => {
  const org = newOrg();
  const team = newTeam();
  const repo = newRepo();

  await signIn(page, seed.alice, seed.alicePass);
  await createOrganization(page, org, org);
  await createTeam(page, org, team);
